10	import org.springframework.jdbc.core.JdbcTemplate;
11	import org.springframework.jdbc.core.RowMapper;
12	import org.springframework.jdbc.support.GeneratedKeyHolder;
13	import org.springframework.jdbc.support.KeyHolder;
14	import org.springframework.stereotype.Repository;
15	
16	import com.example.starter.calibration.model.Certificate;
17	
18	/**
19	 * 校准证书持久化。证书创建后不可修改，仅可撤销；
20	 * 同一仪器的创建通过 instrument_lock 行锁串行化，保证并发下重叠区间最多一张成功。
21	 */
22	@Repository
23	public class CertificateRepository {
24	
25	    private static final RowMapper<Certificate> MAPPER = (rs, rowNum) -> new Certificate(
26	            rs.getLong("id"),
27	            rs.getString("instrument_id"),
28	            JdbcTimes.fromDb(rs.getObject("valid_from", LocalDateTime.class)),
29	            JdbcTimes.fromDb(rs.getObject("valid_to", LocalDateTime.class)),
30	            rs.getBigDecimal("coeff_a"),
31	            rs.getBigDecimal("offset_b"),
32	            rs.getBoolean("revoked"),
33	            JdbcTimes.fromDb(rs.getObject("revoked_at", LocalDateTime.class)),
34	            JdbcTimes.fromDb(rs.getObject("created_at", LocalDateTime.class)));
35	
36	    private final JdbcTemplate jdbc;
37	
38	    public CertificateRepository(JdbcTemplate jdbc) {
39	        this.jdbc = jdbc;
40	    }
41	
42	    /**
43	     * 获取仪器级互斥锁（须在事务内调用）：不存在锁行则插入，随后对该行 FOR UPDATE。
44	     */
45	    public void lockInstrument(String instrumentId) {
46	        try {
47	            jdbc.update("INSERT INTO instrument_lock (instrument_id, created_at) VALUES (?, ?)",
48	                    instrumentId, JdbcTimes.toDb(Instant.now()));
49	        } catch (DuplicateKeyException ignored) {
50	            // 锁行已存在，直接进入行锁等待
51	        }
52	        jdbc.queryForObject("SELECT instrument_id FROM instrument_lock WHERE instrument_id = ? FOR UPDATE",
53	                String.class, instrumentId);
54	    }
55	
56	    /**
57	     * 插入证书并返回生成的证书 ID。
58	     */
59	    public long insert(String instrumentId, Instant validFrom, Instant validTo,
60	                       java.math.BigDecimal a, java.math.BigDecimal b, Instant createdAt) {
